<script lang="ts">
  // The page: a canvas, the input, the frame loop and a small overlay. Everything that decides what
  // is drawn is in the Moddil core; `./core` is generated by `npm run core` (`moddil bind`).
  import { onMount } from "svelte";
  import { Flight, type Camera, type Input } from "./core";

  let canvas: HTMLCanvasElement;
  let flight: Flight | undefined = $state();
  let error = $state("");
  let fps = $state(0);
  let steps = $state(0);
  let power = $state(8);
  let iterations = $state(12);
  let speed = $state(1);

  const keys = new Set<string>();
  let lookYaw = 0;
  let lookPitch = 0;

  $effect(() => flight?.set_power(power));
  $effect(() => flight?.set_iterations(iterations));

  function axis(plus: string, minus: string): number {
    return (keys.has(plus) ? 1 : 0) - (keys.has(minus) ? 1 : 0);
  }

  function input(): Input {
    const i: Input = {
      forward: axis("KeyW", "KeyS"),
      strafe: axis("KeyD", "KeyA"),
      look_yaw: lookYaw,
      look_pitch: lookPitch,
      speed,
    };
    lookYaw = 0;
    lookPitch = 0;
    return i;
  }

  function copyLink() {
    if (!flight) return;
    location.hash = btoa(JSON.stringify(flight.camera()));
    navigator.clipboard.writeText(location.href);
  }

  function restore(f: Flight) {
    if (!location.hash) return;
    try {
      f.set_camera(JSON.parse(atob(location.hash.slice(1))) as Camera);
    } catch {
      // A damaged link starts from the default camera.
    }
  }

  onMount(() => {
    if (!navigator.gpu) {
      error = "This browser has no WebGPU.";
      return;
    }
    let frame = 0;
    let last = performance.now();
    let smoothed = 1 / 60;

    const resize = () => {
      canvas.width = Math.floor(innerWidth * devicePixelRatio);
      canvas.height = Math.floor(innerHeight * devicePixelRatio);
    };
    resize();
    addEventListener("resize", resize);

    Flight.new(canvas.getContext("webgpu")!)
      .then((f) => {
        restore(f);
        flight = f;
        const tick = (now: number) => {
          const dt = Math.min((now - last) / 1000, 0.1);
          last = now;
          f.frame(input(), dt);
          smoothed = smoothed * 0.95 + dt * 0.05;
          fps = Math.round(1 / smoothed);
          steps = f.max_steps();
          frame = requestAnimationFrame(tick);
        };
        frame = requestAnimationFrame(tick);
      })
      .catch((e) => (error = String(e)));

    return () => {
      cancelAnimationFrame(frame);
      removeEventListener("resize", resize);
    };
  });
</script>

<svelte:window
  onkeydown={(e) => keys.add(e.code)}
  onkeyup={(e) => keys.delete(e.code)}
  onmousemove={(e) => {
    if (document.pointerLockElement === canvas) {
      lookYaw += e.movementX * 0.002;
      lookPitch -= e.movementY * 0.002;
    }
  }}
  onwheel={(e) => (speed = Math.min(8, Math.max(0.125, speed * (e.deltaY < 0 ? 1.1 : 0.9))))}
/>

<canvas bind:this={canvas} onclick={() => canvas.requestPointerLock()}></canvas>

<aside>
  {#if error}
    <p class="error">{error}</p>
  {:else}
    <p>{fps} fps · {steps} steps · speed ×{speed.toFixed(2)}</p>
    <label>Power <input type="range" min="2" max="16" step="0.1" bind:value={power} /> {power}</label>
    <label>Iterations <input type="range" min="2" max="32" bind:value={iterations} /> {iterations}</label>
    <button onclick={copyLink}>Copy link</button>
    <p class="hint">Click to fly: mouse to look, WASD to move, wheel for speed, Esc to stop.</p>
  {/if}
</aside>

<style>
  :global(body) {
    margin: 0;
    overflow: hidden;
    background: #000;
    color: #eee;
    font: 13px system-ui, sans-serif;
  }
  canvas {
    display: block;
    width: 100vw;
    height: 100vh;
  }
  aside {
    position: fixed;
    top: 12px;
    left: 12px;
    padding: 8px 12px;
    background: rgb(0 0 0 / 0.55);
    border-radius: 6px;
    display: grid;
    gap: 6px;
  }
  p {
    margin: 0;
  }
  .hint {
    opacity: 0.7;
  }
  .error {
    color: #f88;
  }
</style>
